}

function pz_mistakes_cat_mats_removal_guide() {
    return [
        ['❌ Cutting a mat with sharp, pointed scissors', 'Pointed scissors slid under a mat are a common cause of cut skin because the mat sits so close to the body; use blunt-tip grooming scissors or clippers instead, with a comb as a barrier.'],
        ['❌ Trying to brush out a mat with brute force', 'Yanking a brush through a tight mat is painful for the cat and can tear the skin underneath; loosen it first or get help instead of pulling harder.'],
        ['❌ Restraining a struggling cat alone for a big mat job', 'A large matting job on a stressed cat is safer with a second person helping hold or distract, or left to a professional groomer entirely.'],
        ['❌ Shaving the whole cat yourself without the right clippers', 'Human clippers or dull blades can nick skin and overheat; full-body shaving for severe matting is best done by a groomer or vet with proper equipment.'],
        ['❌ Ignoring repeated mats in the same spot', 'Recurring mats in one area often mean that area needs more frequent brushing attention, not just repeated removal of the same problem.'],
        ['❌ Assuming severe matting is "just a grooming issue"', 'Sudden, widespread matting in a cat that used to groom normally can signal pain, arthritis, obesity, or illness, and is worth mentioning to a vet.'],
